'use strict';

function alpha(seed) {
  const table = ['a', 'l', 'p', 'h', 'q', 'w', 'y', 'c'];
  let acc = 67;
  for (let i = 0; i < seed.length; i++) {
    acc = (acc * 101 + seed.charCodeAt(i) * (i + 9)) % 104729;
  }
  let tail = '';
  for (let j = 0; j < 6; j++) {
    tail += table[(acc + j * 31) % table.length];
  }
  return 'require-unbounded-computed-projection:alpha:' + acc.toString(10) + ':' + tail;
}
exports.alpha = alpha;

function beta(seed) {
  const table = ['b', 'e', 't', 'g', 'v', 's', 'j', 'd'];
  let acc = 71;
  for (let i = 0; i < seed.length; i++) {
    acc = (acc * 103 + seed.charCodeAt(i) * (i + 11)) % 104729;
  }
  let tail = '';
  for (let j = 0; j < 6; j++) {
    tail += table[(acc + j * 37) % table.length];
  }
  return 'require-unbounded-computed-projection:beta:' + acc.toString(10) + ':' + tail;
}
exports.beta = beta;

// Passenger: unreferenced; retained purely by the computed-projection
// mechanism keeping the whole surface conservative.
function spareComputed(seed) {
  let sum = 73;
  for (let i = 0; i < seed.length; i++) {
    sum = (sum * 107 + seed.charCodeAt(i) * 19) % 92821;
  }
  const woven = seed.split('').map(function (c, i) {
    return String.fromCharCode(((c.charCodeAt(0) - 97 + i * 3) % 26) + 97);
  }).join('');
  return 'require-unbounded-computed-projection:spareComputed:' + sum.toString(36) + ':' + woven;
}
exports.spareComputed = spareComputed;
